import{_ as n,C as t,o as s,c as d,E as o,a2 as l}from"./chunks/framework.uPk2SrVb.js";const i="/joinwell52/assets/task-identity-20261029/same-id.figure.zh.svg",f=JSON.parse('{"title":"同一个任务号，就还是同一件工作吗？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"同一个任务号，就还是同一件工作吗？","date":"2026-10-29","published_date":"2026-10-29","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"同一个任务号，就还是同一件工作吗？","summary":"一份旧测试被用来支撑新报告；一份旧任务入档后，新任务又拿到同号。两组 FCoP／CodeFlowMu 对照实验追问：任务身份与证据究竟怎样绑定？","cover":"/assets/task-identity-20261029/same-id.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定公开源码；FCoP v3 兼容路径与 CodeFlowMu-open 的临时项目对照","pageClass":"six-governance-article"},"headers":[],"relativePath":"zh/research/2026-10-29-same-task-id-different-work.md","filePath":"zh/research/2026-10-29-same-task-id-different-work.md","lastUpdated":null}'),c={name:"zh/research/2026-10-29-same-task-id-different-work.md"};function g(p,e,h,u,m,_){const r=t("ArticleCover"),a=t("ArticleTableScroll");return s(),d("div",null,[o(r,{image:"/assets/task-identity-20261029/same-id.cover-v1.png",kicker:"开源工程研究 · 本地对照",title:"同一个任务号，就还是同一件工作吗？",summary:"一份旧测试被用来支撑新报告；一份旧任务入档后，新任务又拿到同号。两组 FCoP／CodeFlowMu 对照实验追问：任务身份与证据究竟怎样绑定？",version:"2026-10-29",languageHref:"/en/research/2026-10-29-same-task-id-different-work",languageLabel:"English"}),o(a,{language:"zh"}),e[0]||(e[0]=l('<h1 id="同一个任务号-就还是同一件工作吗" tabindex="-1">同一个任务号，就还是同一件工作吗？ <a class="header-anchor" href="#同一个任务号-就还是同一件工作吗" aria-label="Permalink to &quot;同一个任务号，就还是同一件工作吗？&quot;">​</a></h1><p>一项工作交给 AI 团队，任务号是 <code>001</code>。执行者做完后写报告，审查者按这个号码找测试记录、产物和历史。只要号码相同，材料似乎就能串起来。</p><p>但我们在临时项目里做了两次对照。第一次，<strong>新会话写的完成报告得到了旧会话的测试支持</strong>。第二次，<strong>旧任务归档后，新任务拿到了旧号码</strong>。两次都没有造成已知的线上事故，却让同一个问题变得具体：一个号码能帮我们找到记录，是否也能证明这些记录属于<strong>这一次工作</strong>？</p><h2 id="两条外部线索-为什么让我们回头检查自己的系统" tabindex="-1">两条外部线索，为什么让我们回头检查自己的系统 <a class="header-anchor" href="#两条外部线索-为什么让我们回头检查自己的系统" aria-label="Permalink to &quot;两条外部线索，为什么让我们回头检查自己的系统&quot;">​</a></h2><p><a href="https://github.com/B0yko/agent-claimcheck" target="_blank" rel="noreferrer">agent-claimcheck</a> 是一款检查 Agent 成功声明的开源工具：它把“做完了”同工具回执和环境状态探针对照，不可验证的声明留给人看。它提醒我们，<strong>完成是一项需要证据的主张</strong>。<a href="https://github.com/gastownhall/beads" target="_blank" rel="noreferrer">Beads</a> 则是编码 Agent 使用的持久化任务与依赖管理工具；其 <a href="https://github.com/gastownhall/beads/pull/7931" target="_blank" rel="noreferrer">#7931</a> 在特定清理路径保留旧身份，防止迟到操作把已清理的标识当作新操作。</p><p>两者研究的不是同一处问题。前者问证据是否支持声明，后者问旧身份清理后还算不算数。我们关心它们的交点，因为自己正在使用两套相邻系统：<strong>FCoP</strong> 以文件记录 AI 团队的任务与报告；<strong>CodeFlowMu</strong> 组织执行、汇集动作记录并处理审查。任务号从一套系统进入另一套系统时，究竟承诺了什么？</p><p>以下实验固定在 2026 年 10 月 29 日核到的公开源码：FCoP 4.0.5 的 <strong>v3 兼容接口</strong>与 CodeFlowMu-open 的公开 <code>main</code>。CodeFlowMu-open 是已冻结的历史公开版，不能代表当前私有产品。我们没有把外部项目的测试当成自己的结果。</p><h2 id="第一处边界-还是同一个任务-却已不是同一次执行" tabindex="-1">第一处边界：还是同一个任务，却已不是同一次执行 <a class="header-anchor" href="#第一处边界-还是同一个任务-却已不是同一次执行" aria-label="Permalink to &quot;第一处边界：还是同一个任务，却已不是同一次执行&quot;">​</a></h2><p>我们先让 FCoP 的兼容接口真正创建任务和完成报告。生成的报告引用任务号，写着 <code>status: done</code>，但<strong>没有会话或运行标识</strong>。这符合该接口当前写出的文件形态。</p><p>接着，给 CodeFlowMu 一个受控的动作记录：同一任务的旧会话在 10:00 运行 <code>npm test</code>，退出码为 0；新会话在 11:00 写出“本次交付测试通过”的报告。新会话本身没有测试动作。我们将 FCoP 生成的报告交给 CodeFlowMu 的实际报告处理入口。</p><table tabindex="0"><thead><tr><th>报告输入</th><th>事实核查</th><th>后续处理</th></tr></thead><tbody><tr><td>FCoP 原样报告：有任务号，没有会话标识</td><td><code>pass</code></td><td>进入后续审查处理</td></tr><tr><td>同一报告明确绑定新会话，其余记录不变</td><td><code>needs_admin</code></td><td>停在待人工核对</td></tr></tbody></table><p>这不是说旧测试一定无效。团队可能合理地复用先前测试，前提是代码、环境和验收条件没有变，且有人明确接受这份继承。实验显示的是另一件事：<strong>仅有任务号时，受测路径会按任务汇集动作证据；它不能从报告本身判断“旧测试被本次交付合法继承”还是“只是碰巧属于同一任务”。</strong> 明确给出新会话后，缺少对应测试便成为可见的不确定状态。</p><p>这里还要区分 CodeFlowMu 的两个入口。<code>review_check</code> 能检查报告与任务是否匹配，却不负责读取被报告提及的产物内容；事实核查在后续的报告处理链中进行。我们用跨项目入口复验了上表结果，不能把单个检查函数的返回值写成“业务完成已批准”。</p><p><img src="'+i+'" alt="任务号相同，但旧会话动作与新报告之间缺少明确的继承关系"></p><p><em>图：第一组受控实验中的证据关联。图中的“待确认”是需要回答的工程问题，并非真实交付已被判错。</em></p><h2 id="第二处边界-工作已经换了-号码却没有换" tabindex="-1">第二处边界：工作已经换了，号码却没有换 <a class="header-anchor" href="#第二处边界-工作已经换了-号码却没有换" aria-label="Permalink to &quot;第二处边界：工作已经换了，号码却没有换&quot;">​</a></h2><p>我们随后检查任务本身的身份。FCoP 的 v3 兼容接口允许把已关闭任务移入按日期保存的深度历史。在临时项目里，当天只有一个任务：先创建 <code>TASK-20261029-001</code>，将其归档并移入历史，再在同一天创建另一项工作。</p><p>新任务再次得到 <code>TASK-20261029-001</code>。旧文件并未消失：按普通任务读取这个号码，返回的是<strong>新任务</strong>；按历史读取同号，返回的是<strong>旧任务</strong>。如果迟到报告只写这个号码，引用本身便不足以指出它究竟在回应哪一代工作。我们确实写出了这样的报告，但<strong>没有测到迟到操作导致真实副作用</strong>。</p><p>这项结果有严格的适用范围。它发生在 FCoP 4.0.5 保留的 <strong>v3 兼容接口</strong>；FCoP 4.0 原生 Core 使用 UUID 任务身份，不能把兼容路径的现象说成 4.0 原生机制的问题。CodeFlowMu-open 自己的任务号分配器会扫描历史：面对历史中的 <code>001</code>，我们的对照得到 <code>002</code>。因此也不能直接断言 CodeFlowMu 所有入口都会复用任务号。</p><h2 id="这其实是一个问题-号码连接了记录-却没有说明记录的来历" tabindex="-1">这其实是一个问题：号码连接了记录，却没有说明记录的来历 <a class="header-anchor" href="#这其实是一个问题-号码连接了记录-却没有说明记录的来历" aria-label="Permalink to &quot;这其实是一个问题：号码连接了记录，却没有说明记录的来历&quot;">​</a></h2><p>第一组实验中，<strong>逻辑任务相同，执行轮次不同</strong>；第二组中，<strong>逻辑任务不同，显示号码相同</strong>。触发机制不一样，审查者遇到的疑问却相同：看到同一个 <code>task_id</code>，还需要什么才能确定“这份证据是在证明眼前这件事”？</p><p>至少要问三个朴素的问题：</p><ol><li><strong>是哪项工作？</strong> 归档或迁移之后，旧身份是否仍被占用，是否存在同号的新任务？</li><li><strong>是哪次执行？</strong> 报告和动作记录来自哪个会话或运行？</li><li><strong>旧证据怎样继承？</strong> 如果允许复用，谁确认其适用范围，哪些变化会使它失效？</li></ol><p>这三问是从本轮实验得到的<strong>下一步研究方向</strong>，不是已经实现的新协议。可能的设计涉及更稳定的任务身份、执行轮次标识和显式的证据继承记录；在决定格式之前，还需检查 FCoP 兼容写入、CodeFlowMu 各个任务创建入口与真实项目的历史分布。</p><p>对使用 Agent 团队的人，眼下就能做一项检查：当系统说“测试通过、任务完成”，请它指出<strong>这次交付对应的测试发生在哪次执行</strong>。如果答案只是一串相同的任务号，证据链还没有讲完。专业读者也许会追问：跨会话协作的旧测试怎样继承才合理？长期历史中又该保存多小的身份记录，才能防止同号误认，同时避免无限保存内容？</p><p>固定提交、实验脚本、逐项结果与限制见<a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-10-29-task-identity/00-report.md" target="_blank" rel="noreferrer">中文实验报告</a>。本轮是临时项目的受控对照，没有统计真实项目发生率，也没有观察到线上误验或重复执行。<a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">研究仓库</a></p>',26))])}const k=n(c,[["render",g]]);export{f as __pageData,k as default};
